<article class="panel"><h2>Matriz de Máxima</h2><div class="table-scroll"><table><thead><tr><th>Proceso</th><th>A</th><th>B</th><th>C</th></tr></thead><tbody><tr><td>P0</td><td>7</td><td>5</td><td>3</td></tr><tr><td>P1</td><td>3</td><td>0</td><td>2</td></tr><tr><td>P2</td><td>9</td><td>0</td><td>2</td></tr><tr><td>P3</td><td>2</td><td>2</td><td>2</td></tr><tr><td>P4</td><td>4</td><td>3</td><td>3</td></tr></tbody></table></div></article>
